CREATE FUNCTION set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at := CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;

CREATE TRIGGER set_customer_updated_at
BEFORE UPDATE ON training.customers
FOR EACH ROW
EXECUTE FUNCTION set_updated_at();

